import assert from 'node:assert/strict';
import test from 'node:test';
import { createHmac } from 'node:crypto';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import type { NewHomeEvent } from './household-types.js';
import { normalizeRingEvent, RingAdapter, RingAuthenticationError, RingPayloadError } from './ring.js';
import { SharmanStore } from './store.js';

// Synthetic identifiers and times in the documented v1.1 envelope; these events
// were constructed locally, not generated by Ring or a physical doorbell.
function fixture(type: 'motion_detected' | 'button_press' = 'motion_detected') {
  return {
    meta: {
      version: '1.1',
      time: '2026-10-21T02:15:31.200155525Z',
      request_id: 'request-test-1',
      account_id: 'account-test-1',
    },
    data: {
      id: 'opaque-event-test-1',
      type,
      attributes: {
        source: 'device-test-1',
        source_type: 'devices',
        timestamp: Date.parse('2026-10-21T02:15:30.000Z'),
        ...(type === 'motion_detected' ? { sub_type: 'human' } : {}),
      },
      relationships: { devices: { links: { self: '/v1/devices/not-the-reporting-device' } } },
    },
  };
}

test('Ring human motion maps to the household ingestion contract with honest test provenance', () => {
  const input = fixture();
  const before = structuredClone(input);
  assert.deepEqual(normalizeRingEvent(input), {
    source: 'ring',
    source_event_id: 'opaque-event-test-1',
    occurred_at: '2026-10-21T02:15:30.000Z',
    event_type: 'motion_detected',
    zone_id: null,
    access_point_id: null,
    subject_id: null,
    severity: 'attention',
    payload: {
      source_device_id: 'device-test-1',
      detection_type: 'human',
      account_id: 'account-test-1',
      request_id: 'request-test-1',
      notification_sent_at: input.meta.time,
      ring_event_type: 'motion_detected',
      ring_payload_version: '1.1',
      ingestion_mode: 'local_test',
    },
  });
  assert.deepEqual(input, before, 'normalization does not mutate the caller payload');
});

test('button presses need no motion subtype and never imply a known human subject', () => {
  const input = fixture('button_press');
  const event = normalizeRingEvent(input);
  assert.equal(event.event_type, 'doorbell_ring');
  assert.equal(event.severity, 'attention');
  assert.equal(event.payload?.detection_type, 'unknown');
  assert.equal(event.subject_id, null);
});

test('motion classification is open-ended and missing classification stays unknown', () => {
  for (const subtype of ['vehicle', 'motion', 'other_motion', 'package_delivery', 'future_ring_subtype', undefined]) {
    const input = fixture();
    input.data.attributes.sub_type = subtype;
    const event = normalizeRingEvent(input);
    assert.equal(event.payload?.detection_type, subtype ?? 'unknown');
    assert.equal(event.severity, 'normal');
  }
});

test('report-era subType and untrusted placement/provenance cannot override the mapping', () => {
  const input = fixture();
  delete input.data.attributes.sub_type;
  const event = normalizeRingEvent({
    ...input,
    zone_id: 'untrusted-zone',
    subject_id: 'untrusted-person',
    payload: { ingestion_mode: 'live', detection_type: 'human' },
    data: { ...input.data, subType: 'human' },
  });
  assert.equal(event.payload?.detection_type, 'unknown');
  assert.equal(event.payload?.ingestion_mode, 'local_test');
  assert.equal(event.severity, 'normal');
  assert.equal(event.zone_id, null);
  assert.equal(event.subject_id, null);
});

test('device placement uses the source attribute and account-scoped trusted resolver', () => {
  const event = normalizeRingEvent(fixture(), (deviceId, accountId) => {
    assert.equal(deviceId, 'device-test-1');
    assert.equal(accountId, 'account-test-1');
    return { zone_id: 'entrance', access_point_id: 'front-door' };
  });
  assert.equal(event.zone_id, 'entrance');
  assert.equal(event.access_point_id, 'front-door');
});

test('malformed and unsupported payloads never reach household ingestion or device resolution', async () => {
  const invalid: unknown[] = [null, [], 'not JSON', {}, { meta: {}, data: {} }];
  for (const [fieldPath, value] of [
    ['meta.version', '1.0'], ['meta.version', 1.1], ['meta.time', 'not a date'],
    ['meta.time', '2026-10-21T02:15:31'], ['meta.time', '2026-02-30T02:15:31Z'],
    ['meta.request_id', '  '], ['meta.account_id', null], ['data.id', ''],
    ['data.type', 'device_online'], ['data.type', 'ding'], ['data.attributes.source', ''],
    ['data.attributes.source_type', 'accounts'], ['data.attributes.timestamp', '1792548930000'],
    ['data.attributes.timestamp', null], ['data.attributes.timestamp', Number.NaN],
    ['data.attributes.timestamp', Infinity], ['data.attributes.timestamp', -1],
    ['data.attributes.timestamp', 1.5], ['data.attributes.timestamp', 253_402_300_800_000],
    ['data.attributes.sub_type', 7], ['data.attributes.sub_type', '   '],
  ] as const) {
    const input = fixture() as Record<string, any>;
    const parts = fieldPath.split('.');
    let target = input;
    for (const part of parts.slice(0, -1)) target = target[part];
    target[parts.at(-1)!] = value;
    invalid.push(input);
  }
  for (const fieldPath of ['meta', 'meta.account_id', 'data', 'data.id', 'data.attributes', 'data.attributes.source', 'data.attributes.timestamp']) {
    const input = fixture() as Record<string, any>;
    const parts = fieldPath.split('.');
    let target = input;
    for (const part of parts.slice(0, -1)) target = target[part];
    delete target[parts.at(-1)!];
    invalid.push(input);
  }

  let calls = 0;
  const adapter = new RingAdapter(() => { calls++; }, () => { calls++; return {}; });
  for (const input of invalid) await assert.rejects(adapter.ingestTestEvent(input), RingPayloadError);
  assert.equal(calls, 0);
});

test('event identity survives webhook request-ID changes; only the household sink owns deduplication', async () => {
  const deliveries: NewHomeEvent[] = [];
  const results = [{ Accepted: 'household-result' }, { Duplicate: 'household-result' }];
  const adapter = new RingAdapter((event) => {
    deliveries.push(event);
    return results[deliveries.length - 1];
  });
  const first = fixture();
  const retry = fixture();
  retry.meta.request_id = 'request-test-retry';
  assert.strictEqual(await adapter.ingestTestEvent(first), results[0]);
  assert.strictEqual(await adapter.ingestTestEvent(retry), results[1]);
  assert.equal(deliveries.length, 2);
  assert.equal(deliveries[0]?.source_event_id, deliveries[1]?.source_event_id);
  assert.notEqual(deliveries[0]?.payload?.request_id, deliveries[1]?.payload?.request_id);
});

test('async household sink results and rejections pass through without automatic write retries', async () => {
  const rejection = { Rejected: { reason: 'Household rejected input' } };
  const adapter = new RingAdapter(async () => rejection);
  assert.strictEqual(await adapter.ingestTestEvent(fixture()), rejection);

  let calls = 0;
  const error = new Error('Household unavailable');
  const unavailable = new RingAdapter(async () => { calls++; throw error; });
  await assert.rejects(unavailable.ingestTestEvent(fixture()), (caught) => caught === error);
  assert.equal(calls, 1);
});

const webhook = { signingKey: 'controlled-test-ring-key', accountId: 'account-test-1', deviceId: 'device-test-1' };
const sign = (body: Buffer) => `sha256=${createHmac('sha256', webhook.signingKey).update(body).digest('hex')}`;

test('webhook verifies exact wire bytes and binds the configured account and device before ingestion', async () => {
  const deliveries: NewHomeEvent[] = [];
  const adapter = new RingAdapter((event) => { deliveries.push(event); return event; }, undefined, webhook);
  const body = Buffer.from(JSON.stringify(fixture(), null, 2));
  const event = await adapter.ingestWebhook(body, sign(body));
  assert.equal(event.payload?.ingestion_mode, 'signed_webhook');
  assert.equal(deliveries.length, 1);
  await assert.rejects(adapter.ingestWebhook(Buffer.from(JSON.stringify(fixture())), sign(body)), RingAuthenticationError);
  for (const signature of [undefined, '', 'sha256=00', `sha256=${'0'.repeat(64)}`, `sha256=${'g'.repeat(64)}`]) {
    await assert.rejects(adapter.ingestWebhook(body, signature), RingAuthenticationError);
  }
  for (const input of [
    { ...fixture(), meta: { ...fixture().meta, account_id: 'other-account' } },
    { ...fixture(), data: { ...fixture().data, attributes: { ...fixture().data.attributes, source: 'other-device' } } },
  ]) {
    const wrongBinding = Buffer.from(JSON.stringify(input));
    await assert.rejects(adapter.ingestWebhook(wrongBinding, sign(wrongBinding)), RingAuthenticationError);
  }
  const malformed = Buffer.from('{not-json');
  await assert.rejects(adapter.ingestWebhook(malformed, sign(malformed)), RingPayloadError);
  await assert.rejects(new RingAdapter(() => {}).ingestWebhook(body, sign(body)), RingAuthenticationError);
  assert.equal(deliveries.length, 1);
});

test('Ring ingestion persists normalized v1 receipts and suppresses concurrent duplicates across restart', async () => {
  const directory = await mkdtemp(path.join(tmpdir(), 'sharman-ring-'));
  try {
    const store = new SharmanStore(directory);
    const adapter = new RingAdapter((event) => store.ingestRingEvent(event));
    const receipts = await Promise.all(Array.from({ length: 8 }, () => adapter.ingestTestEvent(fixture())));
    assert.equal(receipts.filter((entry) => entry.status === 'ingested').length, 1);
    const receipt = receipts[0]!;
    assert.equal(receipt.normalized.schema_version, 1);
    assert.equal(receipt.normalized.sequence_number, 1);
    assert.equal(receipt.normalized.source_event_hash.length, 64);
    assert.equal(receipt.workflow?.agent.name, 'VisitorAgent');
    assert.equal(receipt.workflow?.agent.permissionCeiling, 'LOW_RISK');
    assert.equal(receipt.event.expectedMatch, false);
    assert.equal(receipt.workflow?.agent.forbidden.includes('door.unlock'), true);
    const before = await store.snapshot();
    const reopened = new SharmanStore(directory);
    const duplicate = await new RingAdapter((event) => reopened.ingestRingEvent(event)).ingestTestEvent(fixture());
    assert.equal(duplicate.status, 'duplicate_ignored');
    assert.deepEqual(await reopened.snapshot(), before);
    const denied = await reopened.denyRingUnlock(receipt.event.id);
    assert.equal(denied.event.source, 'ring');
    assert.equal(denied.event.ring?.sourceEventId, fixture().data.id);
    assert.equal(denied.decision, 'denied');
    assert.equal(denied.agent.denialDetail?.requiredPermission, 'HIGH_RISK');
    assert.equal(denied.agent.denialDetail?.delegatedCeiling, 'LOW_RISK');
    assert.equal((await reopened.snapshot()).reminders.length, 0);
  } finally { await rm(directory, { recursive: true, force: true }); }
});

test('non-human motion creates no worker; repeated human events use actual scoped counts', async () => {
  const directory = await mkdtemp(path.join(tmpdir(), 'sharman-ring-classification-'));
  try {
    const store = new SharmanStore(directory);
    const adapter = new RingAdapter((event) => store.ingestRingEvent(event));
    const vehicle = fixture();
    vehicle.data.attributes.sub_type = 'vehicle';
    vehicle.data.id = 'vehicle-event';
    assert.equal((await adapter.ingestTestEvent(vehicle)).workflow, null);
    assert.equal((await store.homeSnapshot()).agents.length, 0);
    const first = await adapter.ingestTestEvent(fixture());
    assert.equal(first.event.occurrenceCount, 1);
    const second = fixture();
    second.data.id = 'human-second-event';
    second.data.attributes.timestamp += 60_000;
    const repeated = await adapter.ingestTestEvent(second);
    assert.equal(repeated.event.occurrenceCount, 2);
    assert.equal(repeated.workflow?.decision, 'approval_required');
    const otherDevice = fixture();
    otherDevice.data.id = 'other-device-event';
    otherDevice.data.attributes.source = 'other-device';
    assert.equal((await adapter.ingestTestEvent(otherDevice)).event.occurrenceCount, 1);
    await assert.rejects(store.denyRingUnlock('missing-recorded-event'));
  } finally { await rm(directory, { recursive: true, force: true }); }
});

test('captured Playground events are parsed generally and marked as user-supplied captures without credentials', async () => {
  const adapter = new RingAdapter((event) => event);
  for (const id of ['fixture-capture-first', 'fixture-capture-different']) {
    const payload = fixture();
    payload.data.id = id;
    const result = await adapter.ingestCapturedPlaygroundEvent({ ...payload, Authorization: 'Bearer fixture-secret', access_token: 'fixture-token' });
    assert.equal(result.source_event_id, id);
    assert.equal(result.payload?.environment, 'developer_playground');
    assert.equal(result.payload?.delivery, 'user_supplied_capture');
    assert.equal(result.payload?.ingestion_mode, 'ring_developer_playground');
    assert(!JSON.stringify(result).includes('fixture-secret'));
    assert(!JSON.stringify(result).includes('fixture-token'));
  }
});
